//! A small FIFO job queue.
pub mod metrics;
pub mod scheduler;
pub mod worker;

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Job {
    pub name: String,
    pub priority: u8,
}

impl Job {
    pub fn new(name: impl Into<String>, priority: u8) -> Self {
        Self {
            name: name.into(),
            priority,
        }
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Queue {
    jobs: Vec<Job>,
}

impl Queue {
    pub fn new() -> Self {
        Self { jobs: Vec::new() }
    }

    pub fn submit(&mut self, job: Job) {
        self.jobs.push(job);
    }

    pub fn drain(&mut self) -> Vec<Job> {
        std::mem::take(&mut self.jobs)
    }

    pub fn len(&self) -> usize {
        self.jobs.len()
    }
}

