    jobs: Vec<String>,
}

impl Queue {
    pub fn new() -> Self {
        Self { jobs: Vec::new() }
    }

    /// Legacy: enqueue by name.
    pub fn push_job(&mut self, name: String) {
        self.jobs.push(name);
    }

    /// Legacy: dequeue the oldest job.
    pub fn run_next(&mut self) -> Option<String> {
        if self.jobs.is_empty() {
            None
        } else {
            Some(self.jobs.remove(0))
        }
    }

    pub fn len(&self) -> usize {
        self.jobs.len()
    }
}

